<?php
function module_order_panel(array $order): void {
    if($intent=module_order_intent((int)$order['id'])){echo '<section class="package-config"><h3>Eigenständiges Zusatzmodul</h3><p>Dieses Modul gehört zu deinem bestehenden Paket. Die erste Zahlung gilt anteilig bis '.date('d.m.Y',(int)$intent['initial_until']).'; danach '.money($intent['recurring_gross_cents']).' inkl. MwSt. pro '.e(cycle($order['billing'])).'.</p><a class="text-link" href="/konto/bestellungen?id='.(int)$intent['parent_order_id'].'">Grundpaket öffnen</a></section>';return;}
    $zeroBase=zero_base_order($order);$intents=customer_module_intents((int)$order['id'],(int)$order['customer_id']);if(!$intents)return;?>
<section class="package-config"><h3>Deine separat gebuchten Zusatzmodule</h3><p><?= $zeroBase?'Dein Grundpreis beträgt 0 €. Für das Grundpaket ist keine PayPal-Zahlung nötig. Abonniere die gewählten Module einzeln. Die Einrichtung beginnt erst, wenn die erste Zahlung für alle ausgewählten Module bestätigt ist.':'Das Grundpaket und jedes kostenpflichtige Zusatzmodul haben ein eigenes PayPal-Abo. Sobald das Grundpaket bezahlt und eingerichtet ist, gibst du die ausgewählten Module einzeln frei. Aktivierung jeweils nach bestätigter Zahlung.' ?></p><?php foreach($intents as $i):$line=json_decode($i['snapshot'],true); ?><div class="customer-feedback"><strong><?= e($line['label']) ?> · <?= (int)$line['quantity'] ?> <?= e($line['unit']) ?></strong><p><?= money(vat_from_net((int)($line['purchase_pricing']['regular_net']??$line['net_cents']))['gross_cents']) ?> inkl. 19 % MwSt. / <?= cycle($order['billing']) ?></p><?php if($i['order_id']): ?><a class="button button-outline button-small" href="/konto/bestellungen?id=<?= (int)$i['order_id'] ?>"><?= $i['applied_at']?'Modulvertrag öffnen':'Modulzahlung fortsetzen' ?></a><?php elseif(($zeroBase && zero_base_checkout_allowed($order)) || (order_payment_allows_provisioning($order) && service_for_order((int)$order['id'],(int)$order['customer_id']))): ?><a class="button button-teal button-small" href="/konto/zusatzmodul?id=<?= (int)$i['id'] ?>">Zusatzmodul mit PayPal abonnieren</a><?php else: ?><p class="small muted">Verfügbar nach Einrichtung des Grundpakets.</p><?php endif ?><?php if(!$i['order_id'] && !$zeroBase): ?><form method="post"><?= csrf() ?><input type="hidden" name="action" value="module_intent_remove"><input type="hidden" name="intent_id" value="<?= (int)$i['id'] ?>"><button class="text-button">Auswahl entfernen</button></form><?php endif ?></div><?php endforeach ?></section><?php
}
function service_module_panel(array $service): void {
    if(!in_array($service['provider'],['ispconfig','proxmox'],true))return;try{$parent=module_parent_for_service($service);$base=module_baseline_profile($service);$offers=module_available_offers($service);}catch(RuntimeException $e){return;}$intents=customer_module_intents((int)$parent['id'],(int)$service['customer_id']); ?>
<section class="panel form-panel" id="paket-module"><h2>Paket & Zusatzmodule verwalten</h2><p>Inklusive Leistungen bleiben fest in deinem Grundpaket. Kostenpflichtige Zusatzmodule kannst du separat nachkaufen oder zum Ende ihres bezahlten Zeitraums kündigen.</p><p><strong>Aktueller Gesamtpreis: <?= money($service['price_cents']??$parent['amount_cents']) ?> inkl. 19 % MwSt. / <?= cycle($parent['billing']) ?></strong></p><?php if(!empty($base['module_selection'])): ?><h3>Fest enthalten</h3><p class="pre-wrap"><?= e(module_description($base['module_selection'])) ?></p><?php endif ?>
<?php foreach($intents as $i):$line=json_decode($i['snapshot'],true);$c=$i['order_id']?contract_for_order((int)$i['order_id']):null; ?><article class="customer-feedback"><h3><?= e($line['label']) ?></h3><p><?= (int)$line['quantity'] ?> <?= e($line['unit']) ?> · <?= money($i['initial_until']?(int)$i['recurring_gross_cents']:vat_from_net((int)($line['purchase_pricing']['regular_net']??$line['net_cents']))['gross_cents']) ?> inkl. MwSt. / <?= cycle($parent['billing']) ?></p><?php if($i['applied_at']): ?><p><?= $c && contract_closed($c)?'Abo beendet'.($i['state']!=='ended'?' · Technische Umstellung wird durch den Support geprüft':''):($c && $c['cancel_at']?'Gekündigt zum '.date('d.m.Y H:i',(int)$c['cancel_at']):'Aktiv'.($c && $c['paid_until']?' · bezahlt bis '.date('d.m.Y',(int)$c['paid_until']):'')) ?></p><?php if($c && !$c['cancel_at'] && !contract_closed($c)): ?><a class="button button-outline button-small" href="/kuendigen?vertrag=<?= e($c['reference']) ?>">Dieses Zusatzmodul kündigen</a><?php endif ?><?php if($c): ?><a class="text-link" href="/konto/vertraege?id=<?= (int)$c['order_id'] ?>">Modulvertrag</a><?php endif ?><?php elseif($i['order_id']): ?><a class="button button-outline button-small" href="/konto/bestellungen?id=<?= (int)$i['order_id'] ?>">Zahlung / Bereitstellung öffnen</a><?php else: ?><a class="button button-teal button-small" href="/konto/zusatzmodul?id=<?= (int)$i['id'] ?>">Auswahl abonnieren</a><?php endif ?></article><?php endforeach ?>
<?php $canBuy=true;try{module_parent_for_service($service,true);}catch(RuntimeException $e){$canBuy=false;}if($canBuy && $offers): ?><h3>Dein Paket erweitern</h3><p>Die erste Zahlung wird bis zum nächsten Abrechnungstermin des Grundpakets anteilig berechnet. Danach läuft jedes Modul als eigenes PayPal-Abo.</p><?php foreach($offers as $m): ?><form method="post" class="customer-feedback"><?= csrf() ?><input type="hidden" name="action" value="module_intent_create"><input type="hidden" name="service_id" value="<?= (int)$service['id'] ?>"><input type="hidden" name="module_id" value="<?= (int)$m['id'] ?>"><input type="hidden" name="purchase_key" value="<?= bin2hex(random_bytes(24)) ?>"><h3><?= e($m['label']) ?></h3><p><?= e($m['description']) ?></p><?php if($m['control']==='select'): ?><label class="field"><span>Option</span><select name="quantity" required><?php foreach($m['options'] as $key=>$option):if(!(int)$option['net_cents'])continue; ?><option value="<?= (int)$key ?>"><?= e($option['label']) ?> · <?= money(vat_from_net((int)$option['net_cents'])['gross_cents']) ?> inkl. MwSt.</option><?php endforeach ?></select></label><?php elseif($m['control']==='checkbox'): ?><input type="hidden" name="quantity" value="1"><p><?= money(vat_from_net((int)$m['net_cents'])['gross_cents']) ?> inkl. 19 % MwSt. pro <?= cycle($parent['billing']) ?></p><?php else: ?><label class="field"><span>Zusätzliche Menge (<?= e($m['unit_label']?:'Einheiten') ?>)</span><input type="number" name="quantity" min="<?= max(1,(int)$m['min_qty']) ?>" <?= (int)$m['max_qty']>0?'max="'.(int)$m['max_qty'].'"':'' ?> step="1" value="<?= max(1,(int)$m['min_qty']) ?>" required><small><?= money(vat_from_net((int)$m['net_cents'])['gross_cents']) ?> inkl. MwSt. je <?= e($m['unit_label']?:'Einheit') ?> / <?= cycle($parent['billing']) ?></small></label><?php endif ?><button class="button button-outline">Preis prüfen & Zusatzmodul buchen</button></form><?php endforeach ?><?php elseif(!$canBuy): ?><p>Für dieses Grundpaket sind momentan keine weiteren Nachkäufe möglich, z. B. während einer Kündigung.</p><?php endif ?><p class="small muted">Bei Verkleinerungen müssen belegter Speicher und vorhandene Zugänge in die verbleibende Ausstattung passen. Eine kleinere VPS-Systemplatte benötigt eine betreute Datenmigration.</p></section><?php
}
function server_reinstall_panel(array $service): void {
    if(proxmox_service_type($service)!=='lxc')return;$parent=module_parent_for_service($service);$templates=server_template_choices((int)$parent['product_id']);$profile=$service['meta']['purchased_profile']??json_decode($parent['profile'],true); ?>
<section class="panel form-panel"><h2>Deine feste Serverausstattung</h2><dl class="detail-list"><div><dt>Servertyp</dt><dd>LXC</dd></div><div><dt>Netzwerk</dt><dd><?= e($service['meta']['network']['address']??$service['identifier']) ?>/<?= (int)($service['meta']['network']['prefix_len']??32) ?> · <?= e($service['meta']['network']['mac']??'') ?></dd></div><div><dt>Gateway / Bridge</dt><dd><?= e($service['meta']['network']['gateway']??'') ?> / <?= e($service['meta']['network']['bridge']??'') ?></dd></div><div><dt>Gekaufte Ressourcen</dt><dd><?= (int)$profile['cores'] ?> vCPU · <?= (int)$profile['memory_mb'] ?> MB RAM · <?= (int)($service['meta']['disk_base_gb']??0)+(int)($profile['disk_extra_gb']??0) ?> GB Systemplatte</dd></div><div><dt>Installierte Vorlage</dt><dd><?= e($service['meta']['server_template']['name']??'') ?></dd></div></dl>
<?php $ops=all('SELECT * FROM shop_server_operations WHERE service_id=? ORDER BY id DESC LIMIT 3',[$service['id']]);foreach($ops as $op): ?><p class="info-box">Neuinstallation: <?= e(['queued'=>'Vorgemerkt','running'=>'In Bearbeitung','waiting'=>'Proxmox-Aufgabe läuft','needs_action'=>'Prüfung durch Support erforderlich','done'=>'Abgeschlossen'][$op['state']]??$op['state']) ?> <?= e($op['last_error']??'') ?></p><?php endforeach ?>
<details><summary>Server neu installieren</summary><p>Alle Daten dieses Containers werden ersetzt. IP-/MAC-Zuordnung und gekaufte CPU-/RAM-Ressourcen bleiben erhalten. Jede Neuinstallation erstellt ein neues Passwort, das du per E-Mail erhältst.</p><form method="post" data-confirm="Diesen Container vollständig neu installieren und alle bisherigen Daten ersetzen?"><?= csrf() ?><input type="hidden" name="action" value="server_reinstall"><input type="hidden" name="service_id" value="<?= (int)$service['id'] ?>"><input type="hidden" name="operation_key" value="<?= bin2hex(random_bytes(24)) ?>"><label class="field"><span>Neue Vorlage</span><select name="server_template" required><?php foreach($templates as $t):if($t['node']!==$service['meta']['node'])continue; ?><option value="<?= (int)$t['id'] ?>"><?= e($t['name']) ?></option><?php endforeach ?></select></label><label class="field"><span>Zur Bestätigung Server-IP eingeben: <?= e($service['identifier']) ?></span><input name="confirmation" required autocomplete="off"></label><button class="button button-outline">Neuinstallation verbindlich starten</button></form></details></section><?php
}
function server_template_picker(array $p,bool $reload=false): void {
    $a=checkout_automation($p);if(($a['settings']['virtualization']??'qemu')!=='lxc')return;$selected=(int)($p['_server_template_id']??$_GET['server_template']??$_POST['server_template']??0); ?>
<label class="field"><span>Betriebssystem & Anwendung</span><select name="server_template" <?= $reload?'data-server-template-reload':'' ?> required><?php foreach(server_template_choices((int)$p['id']) as $t): ?><option value="<?= (int)$t['id'] ?>" <?= $selected===(int)$t['id']?'selected':'' ?>><?= e($t['name']) ?></option><?php endforeach ?></select><small>Die ausgewählte Vorlage wird mit deiner gekauften Ausstattung und einer fest zugeordneten IP-/MAC-Adresse installiert.</small></label><?php
}
